// Inline SVG platform logos.
//
// SOURCING: the path data below for Audiomack, Spotify, Apple Music,
// YouTube Music, YouTube, Deezer, Tidal, SoundCloud, Pandora, iHeartRadio,
// and WhatsApp is taken from Simple Icons (simpleicons.org — CC0-licensed,
// pixel-accurate reproductions of each brand's official mark), not
// hand-drawn. Boomplay and Amazon Music/Napster/Anghami/Yandex Music are
// NOT in that library; Boomplay below is a manual reproduction built
// directly from the brand's own reference images (best-effort, not an
// official source) — the others are simply not included until an
// accurate source is available.
//
// Every icon renders inside a uniform dark "chip" so the row stays
// visually even regardless of whether a brand's own mark includes a
// background shape. `size` controls the chip's pixel size (default 24).

function IconChip({ size, children, bg = "#000000" }) {
  return (
    <div
      className="flex items-center justify-center shrink-0 rounded-md overflow-hidden"
      style={{ width: size, height: size, backgroundColor: bg }}
    >
      {children}
    </div>
  );
}

function BrandMark({ size = 24, viewBox = "0 0 24 24", d, fill, padding = 0.14 }) {
  const inner = Math.round(size * (1 - padding * 2));
  return (
    <svg width={inner} height={inner} viewBox={viewBox}>
      <path d={d} fill={fill} />
    </svg>
  );
}

